// 1. Definisikan Rumus Matematika (Harus di paling atas)
function calculateSMA(data, period) {
    if (data.length < period) return null;
    const subset = data.slice(-period);
    const sum = subset.reduce((a, b) => a + b, 0);
    return sum / period;
}

function calculateRSI(data, period = 14) {
    if (data.length <= period) return null;
    let gains = 0, losses = 0;
    for (let i = data.length - period; i < data.length; i++) {
        const diff = data[i] - data[i - 1];
        if (diff >= 0) gains += diff;
        else losses -= diff;
    }
    const rs = (gains / period) / (losses / period);
    return 100 - (100 / (1 + rs));
}

// 2. Logika Utama untuk Memproses Data
const results = [];

for (const item of items) {
    // Navigasi ke data harga Yahoo Finance berdasarkan skema di image_fb9663.jpg
    const result = item.json.chart.result[0];
    const prices = result.indicators.quote[0].close.filter(p => p !== null);
    const lastPrice = prices[prices.length - 1];

    // Hitung Indikator menggunakan fungsi di atas
    const ma50 = calculateSMA(prices, 50);
    const ma200 = calculateSMA(prices, 200);
    const rsi = calculateRSI(prices, 14);

    // Tentukan Sinyal [cite: 46]
    let signal = "⚪ Tidak ada sinyal saat ini";
    if (ma50 && ma200 && ma50 > ma200) signal = "🚀 Golden Cross (Bullish)";
    else if (rsi && rsi < 30) signal = "🟢 Oversold (Potensi Beli)";
    else if (rsi && rsi > 70) signal = "🔴 Overbought (Potensi Jual)";

    // Masukkan hasil ke array final
    results.push({
        json: {
            symbol: result.meta.symbol,
            price: lastPrice.toFixed(2),
            rsi: rsi ? rsi.toFixed(2) : "Data Kurang",
            ma50: ma50 ? ma50.toFixed(2) : "Data Kurang",
            ma200: ma200 ? ma200.toFixed(2) : "Data Kurang",
            signal: signal
        }
    });
}

return results;

